CREATE TABLE CORE_DIM.T_FACT_WRITE_OFF_BY_ORGANIZATION_DAY_WAWI_ITEM_1 CLUSTER BY (BUS_DT)(
   bus_dt                              DATE            NOT NULL COMMENT 'The business date to which the measures are related.',
   int_org_sid                         NUMBER(38, 0)   NOT NULL COMMENT 'The unique identifier (surrogate key) for the store or warehouse, where the Wawi item_1 had to be written off.',
   int_org_type_cd                     VARCHAR(20)     NOT NULL COMMENT 'The code identifying the discriminators for internal organizations. Here it distinguishes between stores and warehouses (internal companies).',
   wawi_item_sid                       NUMBER(38, 0)   NOT NULL COMMENT 'The unique identifier (surrogate key) of the Wawi item_1 which was written off.',
   wawi_item_variant_sid               NUMBER(38, 0)   NOT NULL COMMENT 'The unique identifier (surrogate key) of the Wawi item_1 variant which was written off.',
   country_org_sid                     NUMBER(38, 0)   NOT NULL COMMENT 'The unique identifier (surrogate key) for the country_1 organization. This is the country_1 organization which is responsible for the store or warehouse (internal company) which has written off the Wawi item.',
   country_org_cd                      VARCHAR(2)      NOT NULL COMMENT 'The code of the business country_1 for which the related country_1 organization is responsible. (The business country_1 is not identical to a political country.) This is the country_1 organization which is responsible for the store or warehouse (internal company) which has written off the Wawi item.',
   write_off_net_val                   NUMBER(38, 5)   COMMENT 'The total net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given Wawi item_1 on that day, independent on the reason. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
   write_off_for_breakage_net_val      NUMBER(38, 5)   COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given Wawi item_1 on that day because of breakage. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
   write_off_for_sell_by_dt_net_val    NUMBER(38, 5)   COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given Wawi item_1 on that day because the sell-by-date has been exceeded. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
   write_off_for_deliv_quality_net_val NUMBER(38, 5)   COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given Wawi item_1 on that day because of quality issues of delivered products. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
   write_off_for_defective_non_food_net_val NUMBER(38, 5)   COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given Wawi item_1 on that day because of defective non-food products. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
   write_off_for_donations_net_val     NUMBER(38, 5)   COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given Wawi item_1 on that day because of donations to charitable organizations. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
   write_off_for_taken_prod_net_val    NUMBER(38, 5)   COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given Wawi item_1 on that day because products were taken, e.g. for the purpose of quality sampling. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
   write_off_for_force_majeure_net_val NUMBER(38, 5)   COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given Wawi item_1 on that day because of force majeure. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
   write_off_for_discounts_net_val     NUMBER(38, 5)   COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given Wawi item_1 on that day because of discounts. Discounts can be given for perishable products in case the sell-by-date is near. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
   write_off_for_stock_clearance_net_val NUMBER(38, 5)   COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given Wawi item_1 on that day because of stock clearance. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
   curr_cd                             VARCHAR(3)      NOT NULL COMMENT 'The code identifying the currency according to ISO-4217.',
   dwh_created_tmsp                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   dwh_updated_tmsp                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
   dwh_load_id                         NUMBER(38, 0)   NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
   dwh_node_cd                         VARCHAR(20)     NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
   CONSTRAINT PK_T_FACT_WRITE_OFF_BY_ORGANIZATION_DAY_WAWI_ITEM PRIMARY KEY (bus_dt, int_org_sid, wawi_item_variant_sid) NOT ENFORCED
 )  COMMENT= 'An aggregate fact holding write-offs and turnover per day, Wawi item_1 variant (the long Wawi number) and internal organization (store or warehouse).';
